import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

type AuditEvent = {
  id: number;
  action: string;
  actor: { id: string; name: string; email: string };
  at: string;
  details: Record<string, unknown>;
};

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Audit Trail"),
      category: "services",
      contact_email: `audit.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const { id: vendorId } = (await created.json()) as { id: string };

  const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);

  // Act: extraction happens in the background, so wait for its audit event.
  let events: AuditEvent[] = [];
  await expect
    .poll(
      async () => {
        const response = await member.get(`/api/vendors/${vendorId}/audit`);
        expect(response.status(), await response.text()).toBe(200);
        events = ((await response.json()) as { items: AuditEvent[] }).items;
        return events.map((e) => e.action);
      },
      { timeout: 30_000 },
    )
    .toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

  // Assert
  expect(events.map((e) => e.action)).toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

  for (const event of events) {
    expect(event.actor.id, `actor id on ${event.action}`).toBeTruthy();
    expect(event.actor.name, `actor name on ${event.action}`).toBeTruthy();
    expect(event.actor.email, `actor email on ${event.action}`).toBe("member@northwind.test");
    expect(Number.isNaN(Date.parse(event.at)), `timestamp on ${event.action}`).toBe(false);
  }

  const times = events.map((e) => Date.parse(e.at));
  for (let i = 1; i < times.length; i++) {
    expect(times[i], `${events[i].action} is not older than ${events[i - 1].action}`).toBeGreaterThanOrEqual(times[i - 1]);
  }
});
